using System;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.SceneManagement;
public static class DreadmarksmanInstaller
{
 [MenuItem("Tools/Before We Fight/Install Dreadmarksmen")]
 public static void Install(){var f=Import("Assets/Art/Imported/Enemies/dreadmarksman_animated.png",39,32,32,"Dreadmarksman");var v=Import("Assets/Art/Imported/Enemies/dreadmarksman_vfx.png",7,64,16,"DreadmarksmanVfx");var prefab=Build(f,v);var scene=EditorSceneManager.OpenScene("Assets/Scenes/Arena.unity",OpenSceneMode.Single);foreach(var g in scene.GetRootGameObjects().Where(x=>x.name.StartsWith("Dreadmarksman ")).ToArray())UnityEngine.Object.DestroyImmediate(g);Vector2[] p={new(8,11),new(-12,1),new(7,-11)};for(int i=0;i<p.Length;i++){var go=(GameObject)PrefabUtility.InstantiatePrefab(prefab,scene);go.name=$"Dreadmarksman {i+1:00}";go.transform.position=p[i];}EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();Debug.Log("Dreadmarksmen installed in Arena.");}
 static Sprite[] Import(string path,int count,int width,int height,string prefix){AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var im=(TextureImporter)AssetImporter.GetAtPath(path);im.textureType=TextureImporterType.Sprite;im.spriteImportMode=SpriteImportMode.Multiple;im.spritePixelsPerUnit=32;im.filterMode=FilterMode.Point;im.textureCompression=TextureImporterCompression.Uncompressed;im.mipmapEnabled=false;var s=new SpriteMetaData[count];for(int i=0;i<count;i++)s[i]=new SpriteMetaData{name=$"{prefix}_{i:000}",rect=new Rect(i*width,0,width,height),alignment=(int)SpriteAlignment.Center,pivot=new(.5f,.5f)};
#pragma warning disable CS0618
 im.spritesheet=s;
#pragma warning restore CS0618
 im.SaveAndReimport();return AssetDatabase.LoadAllAssetsAtPath(path).OfType<Sprite>().OrderBy(x=>x.name,StringComparer.Ordinal).ToArray();}
 static GameObject Build(Sprite[] f,Sprite[] v){var root=new GameObject("Dreadmarksman",typeof(SpriteRenderer),typeof(Rigidbody2D),typeof(CircleCollider2D),typeof(DreadmarksmanEnemy));var sr=root.GetComponent<SpriteRenderer>();sr.sprite=f[0];sr.sortingOrder=23;var rb=root.GetComponent<Rigidbody2D>();rb.gravityScale=0;rb.linearDamping=8;rb.freezeRotation=true;var c=root.GetComponent<CircleCollider2D>();c.radius=.25f;c.isTrigger=true;var so=new SerializedObject(root.GetComponent<DreadmarksmanEnemy>());Assign(so.FindProperty("frames"),f);Assign(so.FindProperty("effectFrames"),v);so.ApplyModifiedPropertiesWithoutUndo();var prefab=PrefabUtility.SaveAsPrefabAsset(root,"Assets/Prefabs/Dreadmarksman.prefab");UnityEngine.Object.DestroyImmediate(root);return prefab;}
 static void Assign(SerializedProperty property,Sprite[] sprites){property.arraySize=sprites.Length;for(int i=0;i<sprites.Length;i++)property.GetArrayElementAtIndex(i).objectReferenceValue=sprites[i];}
}
